let blocks, blockSize, blockMargin, blockOffset, minSize;
let blockArr;
function setup() {
  createCanvas(windowWidth, windowHeight);
	randomSeed(240516)
  initBlocks();
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

  background(10, 10, 15);

  push();
  translate(width / 2, height / 2);
  drawBlocks(blockArr);
  pop();

  pop();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  initBlocks();
}

function initBlocks() {
  let xOffset = random() * 100;
  let yOffset = random() * 100;
  blockNum = 15;
  minSize = max(width, height);
  blockArr = [];
  blockOffset = minSize / 10;
  blockMargin = 0;
  blockSize =
    (minSize - blockOffset * 2 - blockMargin * (blockNum - 1)) / blockNum;
  for (let j = 0; j < blockNum; j++) {
    for (let i = 0; i < blockNum; i++) {
      blockArr.push({
        xOff: xOffset,
        yOff: yOffset,
        col: i,
        row: j,
        x:
          -minSize / 2 +
          blockOffset +
          i * (blockSize + blockMargin) +
          blockSize / 2,
        y:
          -minSize / 2 +
          blockOffset +
          j * (blockSize + blockMargin) +
          blockSize / 2,
        size: blockSize,
      });
    }
  }
}

function drawBlocks(arr) {
  let xOff = cos(radians(4*frameCount)) * 1/5;
  let yOff = sin(radians(3*frameCount)) * 1/5;
  let xOff2 = cos(radians(3*frameCount)) * 1/5;
  let yOff2 = sin(radians(2*frameCount)) * 1/5;
  for (let obj of arr) {
    push();
    translate(obj.x, obj.y);
    // rect(0, 0, obj.size);
    let n = noise(
      obj.xOff + xOff + obj.col / 10,
      obj.yOff + yOff + obj.row / 10,
      frameCount / 200
    );
    let m = noise(
      obj.yOff + xOff2 + obj.col / 10,
      obj.xOff + yOff2 + obj.row / 10,
      frameCount / 200
    );
    let scl = constrain(min(m,n)*2,0,1);
    scale(scl);
    strokeWeight(1/scl);
    rotate((int(min(n,m) * 4) * TWO_PI) / 4);
    switch (int(max(n,m) * 7) % 4) {
      case 0:
        arc(0, 0, obj.size, obj.size, 0, PI / 2, PIE);
        arc(-obj.size/2, 0, obj.size, obj.size, 0, PI / 2, PIE);
        arc(-obj.size/2, -obj.size/2, obj.size, obj.size, 0, PI / 2, PIE);
        arc(0, -obj.size/2, obj.size, obj.size, 0, PI / 2, PIE);
        break;
      case 1:
        arc(0, -obj.size/2, obj.size, obj.size, 0, PI, PIE);
        arc(0, obj.size/2, obj.size, obj.size, PI, PI*2, PIE);
        break;
      case 2:
        arc(-obj.size/2,-obj.size/2,obj.size,obj.size,0,PI/2,PIE);
        arc(+obj.size/2,-obj.size/2,obj.size,obj.size,PI/2,PI,PIE);
        arc(+obj.size/2,+obj.size/2,obj.size,obj.size,PI,PI+PI/2,PIE);
        arc(-obj.size/2,+obj.size/2,obj.size,obj.size,PI+PI/2,PI*2,PIE);
        break;
      case 3:
        arc(0,0,obj.size,obj.size,0,PI/2,PIE);
        arc(0,0,obj.size,obj.size,PI/2,PI,PIE);
        arc(0,0,obj.size,obj.size,PI,PI+PI/2,PIE);
        arc(0,0,obj.size,obj.size,PI+PI/2,PI*2,PIE);
        break;
    }
    pop();
  }
}


// 1. 免疫 DOM 元素建立導致的看門狗攔截
